/* The part both hosts share: a sandboxed Lua state, the script loader and the calls into
 * scripts/main.lua. */
#ifndef LOFTA_LUA_HOST_H
#define LOFTA_LUA_HOST_H

#include <lua.h>
#include <stddef.h>

typedef struct {
    const char *name;
    const char *data;
    unsigned int size;
} EmbeddedScript;

/* Generated by tools/embed_scripts.py, ended by an entry with a NULL name. */
extern const EmbeddedScript EMBEDDED_SCRIPTS[];

/* Called with a message whenever a script fails. */
typedef void (*LuaHostErrorFn)(const char *context, const char *message);

/* What only the host can do, asked for by name: "quit", "fullscreen". */
typedef void (*LuaHostCommandFn)(const char *command);

/* Search folders for require, tried before the embedded scripts. Pass NULL for none. */
typedef struct {
    const char *dirs[3];
    int debug_library; /* tests only: tracebacks and line numbers */
    LuaHostErrorFn on_error;
    LuaHostCommandFn on_command; /* may be NULL: a host without a window ignores these */
    /* may be NULL: writes the offered version into offered and returns a state word. */
    const char *(*update_status)(char *offered, size_t size);
} LuaHostConfig;

lua_State *lua_host_open(const LuaHostConfig *config);
void lua_host_close(lua_State *L);

/* Forgets loaded modules and requires main again. Returns 1 on success. */
int lua_host_load_main(lua_State *L);

/* Calls main.<fn>. Each returns 1 on success. */
int lua_host_call(lua_State *L, const char *fn);
int lua_host_call_str(lua_State *L, const char *fn, const char *arg);
int lua_host_call_xy(lua_State *L, const char *fn, int x, int y);

/* Where the pointer is, in framebuffer pixels: published to scripts as the global table
 * `pointer` so a screen can light up what the cursor is over. Called once a frame; inside 0
 * clears it, which is what a host without a pointer (tests, screenshots) leaves behind. */
void lua_host_set_pointer(lua_State *L, int x, int y, int inside);

/* Publishes files, host commands and the version to scripts as the global table `sys`. */
void lua_host_bind_sys(lua_State *L);

/* Protected call of the function on top of the stack with nargs arguments below it. Any
 * error goes to on_error. Returns 1 on success. */
int lua_host_pcall(lua_State *L, int nargs, int nresults, const char *context);

#endif
